import{_ as t,o as e,c as r,a6 as o}from"./chunks/framework.De615z8S.js";const f=JSON.parse('{"title":"网站、图层、节点与API：选择并跑通制作路线","description":"","frontmatter":{"id":"tool-routes","title":"网站、图层、节点与API：选择并跑通制作路线","chapter":"00","status":"已公开","content_kind":"方法说明","evidence_status":"沿原稿制作路线重写并核对官方文档；未调用生成服务","last_modified":"2026-10-14T00:00:00.000Z","resource_ids":["comfyui","invokeai","rembg"],"tool_ids":["lovart","tapnow","photoshop","krita"],"order":4},"headers":[],"relativePath":"start/tool-routes.md","filePath":"start/tool-routes.md"}'),s={name:"start/tool-routes.md"};function n(i,a,p,l,d,h){return e(),r("div",null,[...a[0]||(a[0]=[o(`<h1 id="网站、图层、节点与api-按当前任务选择路线" tabindex="-1">网站、图层、节点与API，按当前任务选择路线 <a class="header-anchor" href="#网站、图层、节点与api-按当前任务选择路线" aria-label="Permalink to &quot;网站、图层、节点与API，按当前任务选择路线&quot;">​</a></h1><p>原稿把制作分为网站版、工具版和API版。这一章保留分工，去掉计费内容和未经核实的模型排名。先看你手上有什么素材、要交什么文件，再选需要的工具，不用一开始把所有软件都装上。</p><h2 id="一张图-先走网站与图层路线" tabindex="-1">一张图，先走网站与图层路线 <a class="header-anchor" href="#一张图-先走网站与图层路线" aria-label="Permalink to &quot;一张图，先走网站与图层路线&quot;">​</a></h2><p>有真实产品照片，要做场景副图，就用支持参考图的设计画布生成环境，再在PS/Photopea放回真实商品与准确文字。得到图片原文件、可编辑源文件和预览。这条路线的逐步操作、提示词与返工见<a href="./first-image">第一张图</a>。</p><p>Lovart从项目与素材开始，TapNow按图像节点接参考和任务。实际功能以当前界面为准，参考文件的身份和用途先说清楚。<a href="https://www.lovart.ai/docs/getting-started/design-your-first-project" target="_blank" rel="noreferrer">Lovart项目文档</a>、<a href="https://docs.tapnow.ai/en/docs/canvas/generate-and-edit-images" target="_blank" rel="noreferrer">TapNow图像文档</a>。</p><h2 id="主图、参数与logo-图层软件先接管" tabindex="-1">主图、参数与Logo，图层软件先接管 <a class="header-anchor" href="#主图、参数与logo-图层软件先接管" aria-label="Permalink to &quot;主图、参数与Logo，图层软件先接管&quot;">​</a></h2><p>白底主图不一定需要生图，真实商品抠图、轻修、等比缩放和规范导出即可。尺寸、发货数量、Logo与准确文本优先保留可编辑层，方便多语言与SKU版本。操作见<a href="./../ecommerce/amazon-listing">Amazon主图</a>和<a href="./../ecommerce/image-set">套图</a>。</p><p>Photopea可在浏览器打开图像并保存PSD或导出JPG/PNG；PS与Krita按实际软件能力完成蒙版与排版。<a href="https://www.photopea.com/learn/opening-saving" target="_blank" rel="noreferrer">Photopea打开与保存</a>。保存PSD后重新打开检查，文件后缀不能证明文字和图层可编辑。</p><h2 id="重复同一处理-再考虑节点" tabindex="-1">重复同一处理，再考虑节点 <a class="header-anchor" href="#重复同一处理-再考虑节点" aria-label="Permalink to &quot;重复同一处理，再考虑节点&quot;">​</a></h2><p>需要对多张图重复背景编辑时，可以用ComfyUI工作流保留模型、输入、蒙版、提示词与输出路径。先跑官方基础示例理解节点，再改为自己的任务；缺模型或节点先解决环境，不能靠一条提示词补齐。<a href="https://docs.comfy.org/tutorials/basic/inpaint" target="_blank" rel="noreferrer">ComfyUI基础inpaint</a>。</p><p>节点路线的蒙版、采样和保存步骤见<a href="./../workflows/canvases">三类画布</a>。本项目没有实际运行节点，不把社区README的效果视为本项目已验证结果。</p><h2 id="商品库与大量任务-api负责连接而非审核" tabindex="-1">商品库与大量任务，API负责连接而非审核 <a class="header-anchor" href="#商品库与大量任务-api负责连接而非审核" aria-label="Permalink to &quot;商品库与大量任务，API负责连接而非审核&quot;">​</a></h2><p>API路线将商品事实、素材索引和任务表交给已选图像接口，再接收任务结果、下载原图、合成与核对。具体代码必须对应接口当前官方字段、身份配置和错误方式，不能把一个模型的参数套给另一个模型。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>商品事实与素材索引</span></span>
<span class="line"><span>  → 一行一项的任务表</span></span>
<span class="line"><span>  → 已配置的图像生成或编辑接口</span></span>
<span class="line"><span>  → 保存任务ID与状态</span></span>
<span class="line"><span>  → 下载原结果</span></span>
<span class="line"><span>  → 真实主体合成与准确文字</span></span>
<span class="line"><span>  → 逐图核对与交付清单</span></span></code></pre></div><p>网络失败先判断请求是否已经提交，保留原任务ID；有结果但下载失败重试原下载。返回成功只说明接口过程，不证明商品、文字、SKU与渠道要求正确。文件与状态方法见<a href="./../workflows/batch">批量任务</a>。本章没有调用接口、安装工具或建立生成服务。</p><h2 id="下一步直接做一个任务" tabindex="-1">下一步直接做一个任务 <a class="header-anchor" href="#下一步直接做一个任务" aria-label="Permalink to &quot;下一步直接做一个任务&quot;">​</a></h2><table tabindex="0"><thead><tr><th>当前情况</th><th>下一篇</th></tr></thead><tbody><tr><td>只有随手拍，需要第一张场景图</td><td><a href="./first-image">第一张图</a></td></tr><tr><td>已有清晰照片，需要六张商品图</td><td><a href="./../ecommerce/image-set">完整套图</a></td></tr><tr><td>需要十屏详情页</td><td><a href="./../ecommerce/detail-page">逐屏详情页</a></td></tr><tr><td>需要多个渠道与语言</td><td><a href="./../ecommerce/cross-border">跨境制作路径</a></td></tr><tr><td>需要复用节点与图层</td><td><a href="./../workflows/canvases">三类画布</a></td></tr></tbody></table>`,17)])])}const m=t(s,[["render",n]]);export{f as __pageData,m as default};
